  1: //! Operation dispatch and domain-error projection.
  2: //!
  3: //! Routing is closed: the request operation selects exactly one typed backend
  4: //! call. Domain errors are projected onto the fixed protocol error set without
  5: //! leaking backend detail.
  6: 
  7: use super::socket::SocketServer;
  8: use super::wire::{
  9:     ProtocolError, RequestEnvelope, RequestOperation, ResponseBody, ResponseEnvelope,
 10:     PROTOCOL_VERSION,
 11: };
 12: use crate::aggregate::{ApplyRejection, GenerationRejection, IntentError, PlanRejection};
 13: use crate::firewall::FirewallError;
 14: use crate::protocol::capability::NetworkCapabilitySnapshot;
 15: use crate::reconcile::ReconcileError;
 16: use crate::wireguard::WireGuardValidationError;
 17: 
 18: impl SocketServer {
 19:     pub(crate) fn dispatch(&self, request: RequestEnvelope) -> ResponseEnvelope {
 20:         if request.protocol_version != PROTOCOL_VERSION {
 21:             return ResponseEnvelope::failure(
 22:                 request.request_id,
 23:                 ProtocolError::UnsupportedVersion,
 24:             );
 25:         }
 26:         let result = match request.operation {
 27:             RequestOperation::Ping => Ok(ResponseBody::Pong {
 28:                 service: "wg-basic-netd".into(),
 29:                 version: env!("CARGO_PKG_VERSION").into(),
 30:             }),
 31:             RequestOperation::InspectCapabilities => Ok(ResponseBody::Capabilities(
 32:                 NetworkCapabilitySnapshot::observe(&self.runtime_directory),
 33:             )),
 34:             RequestOperation::ObserveWireGuardDevice { interface } => self
 35:                 .wireguard
 36:                 .observe_device(&interface)
 37:                 .map(ResponseBody::WireGuardDevice)
 38:                 .map_err(map_wireguard_error),
 39:             RequestOperation::ApplyWireGuardDevice { interface, patch } => self
 40:                 .wireguard
 41:                 .apply_patch(&interface, patch)
 42:                 .map(ResponseBody::WireGuardApplied)
 43:                 .map_err(map_wireguard_error),
 44:             RequestOperation::PlanManagedInterface { desired } => self
 45:                 .reconciliation
 46:                 .plan(&desired)
 47:                 .map(ResponseBody::ManagedInterfacePlan)
 48:                 .map_err(map_reconcile_error),
 49:             RequestOperation::ApplyManagedInterface { desired } => self
 50:                 .reconciliation
 51:                 .apply(&desired)
 52:                 .map(ResponseBody::ManagedInterfaceApplied)
 53:                 .map_err(map_reconcile_error),
 54:             RequestOperation::PlanNetworkPolicy {
 55:                 installation_id,
 56:                 wireguard_interface,
 57:                 policy,
 58:             } => self
 59:                 .firewall
 60:                 .plan(installation_id, &wireguard_interface, policy.as_ref())
 61:                 .map(ResponseBody::NetworkPolicyPlan)
 62:                 .map_err(map_firewall_error),
 63:             RequestOperation::ApplyNetworkPolicy {
 64:                 installation_id,
 65:                 wireguard_interface,
 66:                 policy,
 67:             } => self
 68:                 .firewall
 69:                 .apply(installation_id, &wireguard_interface, policy.as_ref())
 70:                 .map(ResponseBody::NetworkPolicyApplied)
 71:                 .map_err(map_firewall_error),
 72:             RequestOperation::PlanInstallationNetworkIntent { intent } => self
 73:                 .aggregate
 74:                 .plan(&intent)
 75:                 .map(|plan| {
 76:                     ResponseBody::InstallationNetworkPlanned(
 77:                         crate::protocol::wire::InstallationNetworkPlanBody {
 78:                             installation_id: plan.installation_id,
 79:                             generation: plan.generation,
 80:                             enabling: plan.enabling,
 81:                             interface_plan: plan.interface_plan,
 82:                             firewall_plan: plan.firewall_plan,
 83:                         },
 84:                     )
 85:                 })
 86:                 .map_err(|rejection| match rejection {
 87:                     PlanRejection::Interface(inner) => map_reconcile_error(inner),
 88:                     PlanRejection::Firewall(inner) => map_firewall_error(inner),
 89:                     PlanRejection::InvalidIntent(inner) => map_intent_error(inner),
 90:                     PlanRejection::GenerationRejected(inner) => map_generation_rejection(inner),
 91:                 }),
 92:             RequestOperation::ApplyInstallationNetworkIntent { intent } => self
 93:                 .aggregate
 94:                 .apply(&intent)
 95:                 .map(|receipt| {
 96:                     ResponseBody::InstallationNetworkApplied(
 97:                         crate::protocol::wire::InstallationNetworkApplyBody {
 98:                             installation_id: receipt.installation_id,
 99:                             generation: receipt.generation,
100:                             status: receipt.status,
101:                             interface: receipt.interface,
102:                             firewall: receipt.firewall,
103:                             failed_layer: receipt.failed_layer,
104:                             observed_after: receipt.observed_after,
105:                         },
106:                     )
107:                 })
108:                 .map_err(map_aggregate_error),
109:         };
110:         ResponseEnvelope {
111:             protocol_version: PROTOCOL_VERSION,
112:             request_id: request.request_id,
113:             result,
114:         }
115:     }
116: }
117: 
118: fn map_firewall_error(error: FirewallError) -> ProtocolError {
119:     match error {
120:         FirewallError::InvalidPolicy | FirewallError::ResourceLimitExceeded => {
121:             ProtocolError::InvalidInput
122:         }
123:         FirewallError::TableOwnershipConflict | FirewallError::LegacyTableOwnership => {
124:             ProtocolError::Conflict
125:         }
126:         FirewallError::PermissionDenied => ProtocolError::PermissionDenied,
127:         FirewallError::Unsupported => ProtocolError::UnsupportedBackend,
128:         FirewallError::BackendFailure => ProtocolError::BackendFailure,
129:     }
130: }
131: 
132: fn map_intent_error(error: IntentError) -> ProtocolError {
133:     match error {
134:         IntentError::GenerationOutOfRange => ProtocolError::InvalidInput,
135:         IntentError::InvalidInterface(inner) => map_reconcile_error(inner),
136:         _ => ProtocolError::InvalidInput,
137:     }
138: }
139: 
140: fn map_generation_rejection(error: GenerationRejection) -> ProtocolError {
141:     // A stale generation and a foreign installation identity are both stable
142:     // conflict categories, so no new protocol error variant is needed.
143:     match error {
144:         GenerationRejection::InstallationMismatch | GenerationRejection::Stale { .. } => {
145:             ProtocolError::Conflict
146:         }
147:     }
148: }
149: 
150: fn map_aggregate_error(error: ApplyRejection) -> ProtocolError {
151:     match error {
152:         ApplyRejection::InvalidIntent(intent) => match intent {
153:             IntentError::GenerationOutOfRange => ProtocolError::InvalidInput,
154:             IntentError::InvalidInterface(inner) => map_reconcile_error(inner),
155:             _ => ProtocolError::InvalidInput,
156:         },
157:         ApplyRejection::GenerationRejected(rejection) => match rejection {
158:             GenerationRejection::InstallationMismatch => ProtocolError::Conflict,
159:             GenerationRejection::Stale { .. } => ProtocolError::Conflict,
160:         },
161:         ApplyRejection::Interface(inner) => map_reconcile_error(inner),
162:         ApplyRejection::InterfaceLayerIncomplete { .. } => ProtocolError::InternalFailure,
163:         ApplyRejection::Firewall(inner) => map_firewall_error(inner),
164:         ApplyRejection::FirewallDuringApply { interface, error } => {
165:             // An earlier layer already changed state, so this is a partial
166:             // failure rather than a clean rejection.
167:             if interface.completed_actions > 0 {
168:                 ProtocolError::BackendFailure
169:             } else {
170:                 map_firewall_error(error)
171:             }
172:         }
173:         ApplyRejection::FirewallLayerIncomplete { .. } => ProtocolError::InternalFailure,
174:     }
175: }
176: 
177: fn map_reconcile_error(error: ReconcileError) -> ProtocolError {
178:     match error {
179:         ReconcileError::InvalidDesiredState
180:         | ReconcileError::ResourceLimitExceeded
181:         | ReconcileError::DuplicateResource => ProtocolError::InvalidInput,
182:         // An absent, foreign, or duplicated durable owner tag is a conflict:
183:         // wg-basic cannot prove it owns the link, so it refuses authoritatively.
184:         ReconcileError::OwnershipRequired
185:         | ReconcileError::WrongLinkKind
186:         | ReconcileError::Conflict
187:         | ReconcileError::OwnerTagMissing
188:         | ReconcileError::OwnerTagForeign
189:         | ReconcileError::OwnerTagDuplicated
190:         | ReconcileError::UnlistedResourceOnDelete => ProtocolError::Conflict,
191:         ReconcileError::BackendFailure => ProtocolError::BackendFailure,
192:         ReconcileError::WireGuard(error) => map_wireguard_error(error),
193:     }
194: }
195: 
196: fn map_wireguard_error(error: WireGuardValidationError) -> ProtocolError {
197:     match error {
198:         WireGuardValidationError::PeerNotFound | WireGuardValidationError::InterfaceUnavailable => {
199:             ProtocolError::NotFound
200:         }
201:         WireGuardValidationError::PeerAlreadyExists
202:         | WireGuardValidationError::ConflictingAllowedIps => ProtocolError::Conflict,
203:         WireGuardValidationError::PermissionDenied => ProtocolError::PermissionDenied,
204:         WireGuardValidationError::UnsupportedBackend => ProtocolError::UnsupportedBackend,
205:         WireGuardValidationError::KernelRejected => ProtocolError::KernelRejected,
206:         WireGuardValidationError::InvalidKey | WireGuardValidationError::InvalidBackendInput => {
207:             ProtocolError::InvalidInput
208:         }
209:         WireGuardValidationError::BackendFailure => ProtocolError::BackendFailure,
210:         _ => ProtocolError::InvalidInput,
211:     }
212: }
